BOOL GetStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD dwRead;
    DWORD dwAvail;
    DWORD dwMsgAvail;
    BOOL bResult;

    // Check for data availability in the named pipe
    bResult = PeekNamedPipe(pipe, NULL, 0, &dwRead, &dwAvail, &dwMsgAvail);
    if (!bResult || dwAvail == 0) {
        LogError("PeekNamedPipe failed or no data available in the pipe.");
        return FALSE;
    }

    // Allocate memory to read the data
    char* buffer = (char*)HeapAlloc(GPTR, dwAvail);
    if (!buffer) {
        LogError("Memory allocation for pipe data failed.");
        return FALSE;
    }

    // Read data asynchronously from the pipe
    DWORD dwReadActual;
    bResult = ReadFile(pipe, buffer, dwAvail, &dwReadActual, NULL);
    if (!bResult || dwReadActual == 0) {
        LogError("Failed to read data from the named pipe.");
        HeapFree(buffer);
        return FALSE;
    }

    // Ensure NULL termination
    if (buffer[dwReadActual - 1] != '\0') {
        LogError("Pipe data is not NULL-terminated.");
        HeapFree(buffer);
        return FALSE;
    }

    // Parse data into STARTUP_DATA structure
    char* token = strtok(buffer, "|");
    if (!token) {
        LogError("Startup data parsing failed.");
        HeapFree(buffer);
        return FALSE;
    }

    sud->working_directory = _strdup(token);
    if (!sud->working_directory) {
        LogError("Failed to duplicate working directory string.");
        HeapFree(buffer);
        return FALSE;
    }

    token = strtok(NULL, "|");
    if (!token) {
        LogError("Command line parsing failed.");
        HeapFree(buffer);
        HeapFree(sud->working_directory);
        return FALSE;
    }

    sud->command_line = _strdup(token);
    if (!sud->command_line) {
        LogError("Failed to duplicate command line string.");
        HeapFree(buffer);
        HeapFree(sud->working_directory);
        return FALSE;
    }

    token = strtok(NULL, "|");
    if (!token) {
        sud->stdin_input = NULL;
    } else {
        sud->stdin_input = _strdup(token);
        if (!sud->stdin_input) {
            LogError("Failed to duplicate stdin input string.");
            HeapFree(buffer);
            HeapFree(sud->working_directory);
            HeapFree(sud->command_line);
            return FALSE;
        }
    }

    HeapFree(buffer);
    return TRUE;
}

BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD bytesRead;
    DWORD availableBytes;
    DWORD dummy;
    CHAR* buffer = NULL;
    BOOL success = FALSE;

    if (!PeekNamedPipeAsync(pipe, NULL, 0, &bytesRead, &availableBytes, NULL)) {
        LogError("Failed to peek into named pipe.");
        return FALSE;
    }

    if (availableBytes == 0) {
        LogError("No data available in the named pipe.");
        return FALSE;
    }

    buffer = (CHAR*)HeapAlloc(GetProcessHeap(), GMEM_FIXED, availableBytes + 1);
    if (buffer == NULL) {
        LogError("Failed to allocate memory for buffer.");
        return FALSE;
    }

    if (!ReadFileAsync(pipe, buffer, availableBytes, &bytesRead, NULL)) {
        LogError("Failed to read from named pipe.");
        goto cleanup;
    }

    buffer[availableBytes] = '\0';

    CHAR* workingDir = _strnicmp(buffer, "WorkingDir:", 11) == 0 ? buffer + 11 : "";
    CHAR* commandLine = _strnicmp(buffer, "CommandLine:", 12) == 0 ? buffer + 12 : "";
    CHAR* stdIn = _strnicmp(buffer, "StdIn:", 6) == 0 ? buffer + 6 : "";

    if (!ParseStartupData(sud, workingDir, commandLine, stdIn)) {
        LogError("Failed to parse startup data.");
        goto cleanup;
    }

    success = TRUE;

cleanup:
    if (buffer) {
        HeapFree(GetProcessHeap(), GMEM_FIXED, buffer);
    }

    return success;
}

