BOOL GetStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD bytesRead;
    DWORD totalBytesAvail;
    DWORD bytesToRead;
    CHAR* buffer = NULL;
    BOOL result = FALSE;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &totalBytesAvail, NULL)) {
        DWORD error = GetLastError();
        if (error == ERROR_MORE_DATA) {
            // Ignore the error as it's expected
        } else {
            // Log error
            fprintf(stderr, "PeekNamedPipe failed with error %d\n", GetLastError());
            return FALSE;
        }
    }

    if (totalBytesAvail == 0) {
        // No data available
        return FALSE;
    }

    buffer = (CHAR*)malloc(totalBytesAvail + 1);
    if (buffer == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return FALSE;
    }

    if (!ReadFile(pipe, buffer, totalBytesAvail, &bytesRead, NULL)) {
        fprintf(stderr, "ReadFile failed with error %d\n", GetLastError());
        goto cleanup;
    }

    buffer[totalBytesAvail] = '\0'; // Ensure null termination

    CHAR* workingDir = strtok(buffer, "\n");
    CHAR* commandLine = strtok(NULL, "\n");
    CHAR* stdinInput = strtok(NULL, "\n");

    if (workingDir == NULL || commandLine == NULL || stdinInput == NULL) {
        fprintf(stderr, "Invalid data format.\n");
        goto cleanup;
    }

    strncpy(sud->workingDirectory, workingDir, MAX_PATH - 1);
    strncpy(sud->commandLine, commandLine, MAX_PATH - 1);
    strncpy(sud->standardInput, stdinInput, MAX_PATH - 1);

    result = TRUE;

cleanup:
    if (buffer) {
        free(buffer);
    }

    return result;
}

BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD bytesRead;
    DWORD available;
    BOOL result;

    // Check if data is available in the pipe
    result = PeekNamedPipe(pipe, NULL, 0, NULL, &available, NULL);
    if (!result || available == 0) {
        LogError("Failed to read data from pipe or no data available.");
        return FALSE;
    }

    // Allocate memory to hold the data
    char* buffer = (char*)malloc(available);
    if (buffer == NULL) {
        LogError("Failed to allocate memory for pipe data.");
        return FALSE;
    }

    // Read data from the pipe
    result = ReadFile(pipe, buffer, available, &bytesRead, NULL);
    if (!result || bytesRead != available) {
        free(buffer);
        LogError("Failed to read all data from the pipe.");
        return FALSE;
    }

    // Check for proper NULL termination
    if (buffer[available - 1] != '\0') {
        free(buffer);
        LogError("Data in pipe is not NULL-terminated.");
        return FALSE;
    }

    // Parse the buffer into working directory, command line, and standard input
    char* token = strtok(buffer, "\0");
    if (token == NULL) {
        free(buffer);
        LogError("Invalid data format in pipe.");
        return FALSE;
    }

    sud->workingDirectory = _strdup(token);
    if (sud->workingDirectory == NULL) {
        free(buffer);
        LogError("Failed to duplicate working directory string.");
        return FALSE;
    }

    token = strtok(NULL, "\0");
    if (token == NULL) {
        free(buffer);
        free(sud->workingDirectory);
        sud->workingDirectory = NULL;
        LogError("Invalid data format in pipe.");
        return FALSE;
    }

    sud->commandLine = _strdup(token);
    if (sud->commandLine == NULL) {
        free(buffer);
        free(sud->workingDirectory);
        LogError("Failed to duplicate command line string.");
        return FALSE;
    }

    token = strtok(NULL, "\0");
    if (token == NULL) {
        free(buffer);
        free(sud->workingDirectory);
        free(sud->commandLine);
        sud->workingDirectory = NULL;
        sud->commandLine = NULL;
        LogError("Invalid data format in pipe.");
        return FALSE;
    }

    sud->standardInput = _strdup(token);
    if (sud->standardInput == NULL) {
        free(buffer);
        free(sud->workingDirectory);
        free(sud->commandLine);
        LogError("Failed to duplicate standard input string.");
        return FALSE;
    }

    free(buffer);
    return TRUE;
}

